SELECT FROM ydsz_flow_skip WHERE definition_id = #{definitionId} AND flow_code IN ( SELECT flow_code FROM ydsz_flow_node WHERE definition_id = #{definitionId} AND node_code = #{nodeCode} AND deleted = 0 )
AND skip_type = #{skipType}
AND status = 'ENABLED' AND deleted = 0 ORDER BY id ASC
